/* TEMA: COMPARAÇÃO. for: “quantas vezes?” while: “até quando?” do-while: “executar antes de testar?”. */
public class ComparacaoDosLoops { public static void main(String[] args) { for (int i=0;i<1;i++) System.out.println("for"); int x=0; while(x++<1) System.out.println("while"); do { System.out.println("do"); } while(false); } }
